INSERT INTO public.canonical_syllabus (
  subject, unit_number, unit_name, unit_name_en, unit_name_si, unit_name_ta,
  sub_lesson_code, sub_lesson_title, sub_lesson_title_en, sub_lesson_title_si, sub_lesson_title_ta
) VALUES
('POL_SCI', 1, 'Unit 1: Understanding Political Science & Core Concepts', 'Understanding Political Science & Core Concepts', 'ඒකකය 01: දේශපාලන විද්‍යාව සහ මූලික සංකල්ප', 'அலகு 01: அரசியல் அறிவியலும் அடிப்படைக் கருத்துக்களும்', '1.1', 'Nature, scope and importance of studying political science', 'Nature, scope and importance of studying political science', 'දේශපාලන විද්‍යාවේ ස්වභාවය, විෂය පථය සහ වැදගත්කම', 'அரசியல் அறிவியலின் தன்மையும் எல்லையும் முக்கியத்துவமும்'),
('POL_SCI', 1, 'Unit 1: Understanding Political Science & Core Concepts', 'Understanding Political Science & Core Concepts', 'ඒකකය 01: දේශපාලන විද්‍යාව සහ මූලික සංකල්ප', 'அலகு 01: அரசியல் அறிவியலும் அடிப்படைக் கருத்துக்களும்', '1.2', 'Key concepts: Power, authority, legitimacy and sovereignty', 'Key concepts: Power, authority, legitimacy and sovereignty', 'මූලික සංකල්ප: බලය, අධිකාරය, නීත්‍යානුකූලභාවය සහ ස්වෛරීභාවය', 'முக்கிய கருத்துக்கள்: அதிகாரம், அதிகாரமளிப்பு, சட்டபூர்வத்தன்மை மற்றும் இறைமை'),
('POL_SCI', 2, 'Unit 2: Approaches to the Study of Politics', 'Approaches to the Study of Politics', 'ඒකකය 02: දේශපාලනය හැදෑරීමේ ප්‍රවේශයන්', 'அலகு 02: அரசியலைக் கற்பதற்கான அணுகுமுறைகள்', '2.1', 'Traditional, institutional and philosophical approaches', 'Traditional, institutional and philosophical approaches', 'සාම්ප්‍රදායික, ආයතනික සහ දාර්ශනික ප්‍රවේශ', 'பாரம்பரிய, நிறுவன மற்றும் தத்துவார்த்த அணுகுமுறைகள்'),
('POL_SCI', 2, 'Unit 2: Approaches to the Study of Politics', 'Approaches to the Study of Politics', 'ඒකකය 02: දේශපාලනය හැදෑරීමේ ප්‍රවේශයන්', 'அலகு 02: அரசியலைக் கற்பதற்கான அணுகுமுறைகள்', '2.2', 'Modern behavioral and post-behavioral approaches', 'Modern behavioral and post-behavioral approaches', 'නූතන චර්යාවාදී සහ පසු-චර්යාවාදී ප්‍රවේශ', 'நவீன நடத்தைவாத மற்றும் பிந்தைய நடத்தைவாத அணுகுமுறைகள்'),
('POL_SCI', 3, 'Unit 3: The State and Theories of Origin', 'The State and Theories of Origin', 'ඒකකය 03: රාජ්‍යය සහ සම්භවය පිළිබඳ න්‍යායයන්', 'அலகு 03: அரசும் அதன் தோற்றக் கோட்பாடுகளும்', '3.1', 'Elements of the state and evolutionary/social contract theories', 'Elements of the state and evolutionary/social contract theories', 'රාජ්‍යයේ මූලද්‍රව්‍ය සහ පරිණාමවාදී/සමාජ සම්මුති න්‍යාය', 'அரசின் மூலகங்களும் கூர்ப்பு/சமூக ஒப்பந்தக் கோட்பாடுகளும்'),
('POL_SCI', 3, 'Unit 3: The State and Theories of Origin', 'The State and Theories of Origin', 'ඒකකය 03: රාජ්‍යය සහ සම්භවය පිළිබඳ න්‍යායයන්', 'அலகு 03: அரசும் அதன் தோற்றக் கோட்பாடுகளும்', '3.2', 'Liberal, Marxist and feminist perspectives on the state', 'Liberal, Marxist and feminist perspectives on the state', 'රාජ්‍යය පිළිබඳ ලිබරල්වාදී, මාක්ස්වාදී සහ ස්ත්‍රීවාදී දෘෂ්ටිකෝණ', 'அரசு பற்றிய தாராளவாத, மார்க்சிய மற்றும் பெண்ணியக் கண்ணோட்டங்கள்'),
('POL_SCI', 4, 'Unit 4: Forms and Systems of Government', 'Forms and Systems of Government', 'ඒකකය 04: ආණ්ඩු ක්‍රම සහ ආකෘති', 'அலகு 04: அரசாங்க வடிவங்களும் முறைகளும்', '4.1', 'Unitary and Federal forms of government', 'Unitary and Federal forms of government', 'ඒකීය සහ සන්ධීය ආණ්ඩු ක්‍රම', 'ஒற்றையாட்சி மற்றும் சமஷ்டி அரசாங்க வடிவங்கள்'),
('POL_SCI', 4, 'Unit 4: Forms and Systems of Government', 'Forms and Systems of Government', 'ඒකකය 04: ආණ්ඩු ක්‍රම සහ ආකෘති', 'அலகு 04: அரசாங்க வடிவங்களும் முறைகளும்', '4.2', 'Parliamentary, Presidential and Semi-Presidential systems', 'Parliamentary, Presidential and Semi-Presidential systems', 'පාර්ලිමේන්තු, ජනාධිපති සහ අර්ධ-ජනාධිපති ක්‍රම', 'பாராளுமன்ற, ஜனாதிபதி மற்றும் அரை-ஜனாதிபதி ஆட்சிமுறைகள்'),
('POL_SCI', 5, 'Unit 5: Political Ideologies', 'Political Ideologies', 'ඒකකය 05: දේශපාලන මතවාද', 'அலகு 05: அரசியல் சித்தாந்தங்கள்', '5.1', 'Liberalism, Socialism and Social Democracy', 'Liberalism, Socialism and Social Democracy', 'ලිබරල්වාදය, සමාජවාදය සහ ප්‍රජාතන්ත්‍රවාදී සමාජවාදය', 'தாராளவாதம், சோசலிசம் மற்றும் சமூக ஜனநாயகவாதம்'),
('POL_SCI', 5, 'Unit 5: Political Ideologies', 'Political Ideologies', 'ඒකකය 05: දේශපාලන මතවාද', 'அலகு 05: அரசியல் சித்தாந்தங்கள்', '5.2', 'Fascism, Nationalism, Secularism and Feminism', 'Fascism, Nationalism, Secularism and Feminism', 'ෆැසිස්ට්වාදය, ජාතිකවාදය, අනාගමිකවාදය සහ ස්ත්‍රීවාදය', 'பாசிசம், தேசியவாதம், மதச்சார்பின்மை மற்றும் பெண்ணியம்'),
('POL_SCI', 6, 'Unit 6: Conflict & Conflict Resolution', 'Conflict & Conflict Resolution', 'ඒකකය 06: ගැටුම් සහ ගැටුම් නිරාකරණය', 'அலகு 06: முரண்பாடுகளும் முரண்பாடு தீர்த்தலும்', '6.1', 'Causes and dynamics of social and political conflicts', 'Causes and dynamics of social and political conflicts', 'සමාජ හා දේශපාලන ගැටුම්වල හේතු සහ ගතිකයන්', 'சமூக மற்றும் அரசியல் முரண்பாடுகளுக்கான காரணங்களும் இயக்கங்களும்'),
('POL_SCI', 6, 'Unit 6: Conflict & Conflict Resolution', 'Conflict & Conflict Resolution', 'ඒකකය 06: ගැටුම් සහ ගැටුම් නිරාකරණය', 'அலகு 06: முரண்பாடுகளும் முரண்பாடு தீர்த்தலும்', '6.2', 'Conflict management, peacebuilding and reconciliation mechanisms', 'Conflict management, peacebuilding and reconciliation mechanisms', 'ගැටුම් කළමනාකරණය, සාමය ගොඩනැගීම සහ සංහිඳියා ක්‍රමවේද', 'முரண்பாட்டு முகாமைத்துவம், சமாதானக் கட்டமைப்பு மற்றும் நல்லிணக்க வழிமுறைகள்'),
('POL_SCI', 7, 'Unit 7: Democracy & Good Governance', 'Democracy & Good Governance', 'ඒකකය 07: ප්‍රජාතන්ත්‍රවාදය සහ යහපාලනය', 'அலகு 07: ஜனநாயகமும் நல்லாட்சியும்', '7.1', 'Principles, models and institutions of representative democracy', 'Principles, models and institutions of representative democracy', 'නියෝජිත ප්‍රජාතන්ත්‍රවාදයේ මූලධර්ම, ආකෘති සහ ආයතන', 'பிரதிநிதித்துவ ஜனநாயகத்தின் கோட்பாடுகள், மாதிரிகள் மற்றும் நிறுவனங்கள்'),
('POL_SCI', 7, 'Unit 7: Democracy & Good Governance', 'Democracy & Good Governance', 'ඒකකය 07: ප්‍රජාතන්ත්‍රවාදය සහ යහපාලනය', 'அலகு 07: ஜனநாயகமும் நல்லாட்சியும்', '7.2', 'Good governance: Rule of law, transparency and accountability', 'Good governance: Rule of law, transparency and accountability', 'යහපාලනය: නීතියේ ආධිපත්‍යය, විනිවිදභාවය සහ වගවීම', 'நல்லாட்சி: சட்டத்தின் ஆட்சி, வெளிப்படைத்தன்மை மற்றும் பொறுப்புக்கூறல்'),
('POL_SCI', 8, 'Unit 8: Political Culture & Socialization', 'Political Culture & Socialization', 'ඒකකය 08: දේශපාලන සංස්කෘතිය සහ සමාජානුයෝජනය', 'அலகு 08: அரசியல் கலாச்சாரமும் சமூகமயமாக்கலும்', '8.1', 'Types of political culture and civic attitudes', 'Types of political culture and civic attitudes', 'දේශපාලන සංස්කෘති වර්ග සහ පුරවැසි ආකල්ප', 'அரசியல் கலாச்சார வகைகள் மற்றும் பிரஜைகளின் மனப்பாங்குகள்'),
('POL_SCI', 8, 'Unit 8: Political Culture & Socialization', 'Political Culture & Socialization', 'ඒකකය 08: දේශපාලන සංස්කෘතිය සහ සමාජානුයෝජනය', 'அலகு 08: அரசியல் கலாச்சாரமும் சமூகமயமாக்கலும்', '8.2', 'Agents of political socialization and public opinion', 'Agents of political socialization and public opinion', 'දේශපාලන සමාජානුයෝජන නියෝජිතයන් සහ මහජන මතය', 'அரசியல் சமூகமயமாக்கல் முகவர்களும் பொதுக் கருத்தும்'),
('POL_SCI', 9, 'Unit 9: Political Parties & Interest Groups', 'Political Parties & Interest Groups', 'ඒකකය 09: දේශපාලන පක්ෂ සහ බලපෑම් කණ්ඩායම්', 'அலகு 09: அரசியல் கட்சிகளும் ஆர்வக் குழுக்களும்', '9.1', 'Functions of political parties and party systems', 'Functions of political parties and party systems', 'දේශපාලන පක්ෂවල කාර්යභාරය සහ පක්ෂ ක්‍රම', 'அரசியல் கட்சிகளின் தொழிற்பாடுகளும் கட்சி முறைகளும்'),
('POL_SCI', 9, 'Unit 9: Political Parties & Interest Groups', 'Political Parties & Interest Groups', 'ඒකකය 09: දේශපාලන පක්ෂ සහ බලපෑම් කණ්ඩායම්', 'அலகு 09: அரசியல் கட்சிகளும் ஆர்வக் குழுக்களும்', '9.2', 'Interest groups, civil society and advocacy movements', 'Interest groups, civil society and advocacy movements', 'බලපෑම් කණ්ඩායම්, සිවිල් සමාජය සහ මහජන ව්‍යාපාර', 'ஆர்வக் குழுக்கள், சிவில் சமூகம் மற்றும் வக்காலத்து இயக்கங்கள்'),
