('BUDDHIST_CULTURE', 6, 'Unit 6: Buddhist Art, Architecture & Sculpture in Sri Lanka', 'Buddhist Art, Architecture & Sculpture in Sri Lanka', 'ඒකකය 06: බෞද්ධ කලා, වාස්තුවිද්‍යා සහ මූර්ති', 'அலகு 06: பௌத்த கலை மற்றும் கட்டிடக்கலை', '6.2', 'Buddha statues (Samadhi, Avukana) and Sigiri/Tivanka murals', 'Buddha statues (Samadhi, Avukana) and Sigiri/Tivanka murals', 'බුද්ධ ප්‍රතිමා (සමාධි, අවුකන) සහ තිවංක පිළිමගෙය/සීගිරි බිතුසිතුවම්', 'புத்தர் சிலைகள் (சமாதி, அவுக்கண) மற்றும் சுவரோவியங்கள்'),
('BUDDHIST_CULTURE', 7, 'Unit 7: Buddhist Social Philosophy & Human Values', 'Buddhist Social Philosophy & Human Values', 'ඒකකය 07: බෞද්ධ සමාජ දර්ශනය සහ මානව සාරධර්ම', 'அலகு 07: சமூகத் தத்துவமும் மனித விழுமியங்களும்', '7.1', 'Sigalovada Sutta: Family relationships, social harmony and duties', 'Sigalovada Sutta: Family relationships, social harmony and duties', 'සිඟාලෝවාද සූත්‍රය: පවුල් සබඳතා, සමාජ සහජීවනය සහ යුතුකම්', 'சிங்காலோவாத சூத்திரம்: குடும்ப உறவுகள், சமூக நல்லிணக்கம்'),
('BUDDHIST_CULTURE', 7, 'Unit 7: Buddhist Social Philosophy & Human Values', 'Buddhist Social Philosophy & Human Values', 'ඒකකය 07: බෞද්ධ සමාජ දර්ශනය සහ මානව සාරධර්ම', 'அலகு 07: சமூகத் தத்துவமும் மனித விழுமியங்களும்', '7.2', 'Buddhist political philosophy: Cakkavatti Sihanada and Agganna Sutta', 'Buddhist political philosophy: Cakkavatti Sihanada and Agganna Sutta', 'බෞද්ධ දේශපාලන දර්ශනය: චක්කවත්ති සීහනාද සහ අග්ගඤ්ඤ සූත්‍ර', 'பௌத்த அரசியல் தத்துவம்: சக்கவத்தி சீஹநாத மற்றும் அக்கஞ்ஞ சூத்திரங்கள்'),
('BUDDHIST_CULTURE', 8, 'Unit 8: Buddhism, Ecology & Contemporary Global Challenges', 'Buddhism, Ecology & Contemporary Global Challenges', 'ඒකකය 08: පාරිසරික සදාචාරය සහ ගෝලීය අභියෝග', 'அலகு 08: சூழலியலும் சமகால சவால்களும்', '8.1', 'Buddhist environmental ethics, compassion towards nature and living beings', 'Buddhist environmental ethics, compassion towards nature and living beings', 'බෞද්ධ පාරිසරික ආචාරධර්ම, සොබාදහමට සහ සතුන්ට දයාව දැක්වීම', 'பௌத்த சுற்றுச்சூழல் அறவியல், இயற்கை மற்றும் உயிரினங்கள் மீதான கருணை'),
('BUDDHIST_CULTURE', 8, 'Unit 8: Buddhism, Ecology & Contemporary Global Challenges', 'Buddhism, Ecology & Contemporary Global Challenges', 'ඒකකය 08: පාරිසරික සදාචාරය සහ ගෝලීය අභියෝග', 'அலகு 08: சூழலியலும் சமகால சவால்களும்', '8.2', 'Conflict resolution, global peace and mental wellbeing in modern life', 'Conflict resolution, global peace and mental wellbeing in modern life', 'ගැටුම් නිරාකරණය, ලෝක සාමය සහ නූතන ජීවිතයේ මානසික සුවතාව', 'முரண்பாடுகளைத் தீர்த்தல், உலக அமைதி மற்றும் நவீன வாழ்வில் மனநலன்')
ON CONFLICT (subject, sub_lesson_code) DO UPDATE SET
  unit_number = EXCLUDED.unit_number,
  unit_name = EXCLUDED.unit_name,
  unit_name_en = EXCLUDED.unit_name_en,
  unit_name_si = EXCLUDED.unit_name_si,
  unit_name_ta = EXCLUDED.unit_name_ta,
  sub_lesson_title = EXCLUDED.sub_lesson_title,
  sub_lesson_title_en = EXCLUDED.sub_lesson_title_en,
  sub_lesson_title_si = EXCLUDED.sub_lesson_title_si,
  sub_lesson_title_ta = EXCLUDED.sub_lesson_title_ta;

-- 3. Comprehensive helper function to seed user syllabus from canonical data
CREATE OR REPLACE FUNCTION public.seed_user_syllabus_from_canonical(p_user_id UUID)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_sub RECORD;
  v_unit RECORD;
  v_unit_id UUID;
  v_canon_sub TEXT;
BEGIN
  FOR v_sub IN SELECT id, slug, code, name FROM public.subjects WHERE user_id = p_user_id LOOP
    -- Determine canonical subject key
    v_canon_sub := NULL;
    
    -- Arts Stream
    IF UPPER(v_sub.code) IN ('POL_SCI', '24', 'AL-012', 'SUBJ-012') 
       OR v_sub.slug ILIKE '%politi%' 
       OR v_sub.name ILIKE '%political science%' THEN
      v_canon_sub := 'POL_SCI';
    ELSIF UPPER(v_sub.code) IN ('LOGIC', '25', 'AL-013', 'SUBJ-013') 
       OR v_sub.slug ILIKE '%logic%' 
       OR v_sub.name ILIKE '%logic%' THEN
      v_canon_sub := 'LOGIC';
    ELSIF UPPER(v_sub.code) IN ('GEOGRAPHY', '22', 'AL-014', 'SUBJ-014') 
       OR v_sub.slug ILIKE '%geograph%' 
       OR v_sub.name ILIKE '%geography%' THEN
      v_canon_sub := 'GEOGRAPHY';
    ELSIF UPPER(v_sub.code) IN ('MEDIA', '29', 'AL-019', 'SUBJ-019') 
       OR v_sub.slug ILIKE '%media%' 
       OR v_sub.name ILIKE '%communication%' OR v_sub.name ILIKE '%media%' THEN
      v_canon_sub := 'MEDIA';
    ELSIF UPPER(v_sub.code) IN ('SINHALA', '41', 'AL-015', 'SUBJ-015') 
       OR v_sub.slug ILIKE '%sinhala%' 
       OR v_sub.name ILIKE '%sinhala%' THEN
      v_canon_sub := 'SINHALA';
    ELSIF UPPER(v_sub.code) IN ('BUDDHIST_CULTURE', '43', 'AL-017', 'SUBJ-017') 
       OR v_sub.slug ILIKE '%buddhist%' 
       OR v_sub.name ILIKE '%buddhist culture%' THEN
      v_canon_sub := 'BUDDHIST_CULTURE';

    -- Mathematics Stream
    ELSIF UPPER(v_sub.code) IN ('COMB_MATH', 'MATH', '12', 'AL-004', 'SUBJ-004') 
       OR v_sub.slug ILIKE '%comb%math%' 
       OR (v_sub.slug ILIKE '%math%' AND v_sub.slug NOT ILIKE '%high%') 
       OR v_sub.name ILIKE '%combined mathematics%' 
       OR (v_sub.name ILIKE '%mathematics%' AND v_sub.name NOT ILIKE '%higher%') THEN
      v_canon_sub := 'COMB_MATH';
    ELSIF UPPER(v_sub.code) IN ('HIGH_MATH', '13', 'AL-021', 'SUBJ-021') 
       OR v_sub.slug ILIKE '%high%math%' 
       OR v_sub.name ILIKE '%higher mathematics%' THEN
      v_canon_sub := 'HIGH_MATH';

    -- Biological Science Stream
    ELSIF UPPER(v_sub.code) IN ('BIO', '09', 'AL-001', 'SUBJ-001') OR v_sub.slug ILIKE '%bio%' OR v_sub.name ILIKE '%biology%' THEN
      v_canon_sub := 'BIO';
    ELSIF UPPER(v_sub.code) IN ('CHEM', '10', 'AL-002', 'SUBJ-002') OR v_sub.slug ILIKE '%chem%' OR v_sub.name ILIKE '%chemistry%' THEN
      v_canon_sub := 'CHEM';
    ELSIF UPPER(v_sub.code) IN ('PHYS', '01', 'AL-003', 'SUBJ-003') OR v_sub.slug ILIKE '%phys%' OR v_sub.name ILIKE '%physics%' THEN
      v_canon_sub := 'PHYS';
    ELSIF UPPER(v_sub.code) IN ('AGRI', '08', 'AL-006', 'SUBJ-006') OR v_sub.slug ILIKE '%agri%' OR v_sub.name ILIKE '%agri%' THEN
      v_canon_sub := 'AGRI';

    -- Technology Stream
    ELSIF UPPER(v_sub.code) IN ('ET', 'AL-007', 'SUBJ-007') OR v_sub.slug ILIKE '%et%' OR v_sub.name ILIKE '%engineering tech%' THEN
      v_canon_sub := 'ET';
    ELSIF UPPER(v_sub.code) IN ('SFT', 'AL-008', 'SUBJ-008') OR v_sub.slug ILIKE '%sft%' OR v_sub.name ILIKE '%science for tech%' THEN
      v_canon_sub := 'SFT';
    ELSIF UPPER(v_sub.code) IN ('ICT', '005', 'AL-005', 'SUBJ-005') OR v_sub.slug ILIKE '%ict%' OR v_sub.name ILIKE '%information%' THEN
      v_canon_sub := 'ICT';

    ELSE
      -- Fallback to exact match with code or slug
      SELECT subject INTO v_canon_sub FROM public.canonical_syllabus 
      WHERE UPPER(subject) = UPPER(v_sub.code) OR UPPER(subject) = UPPER(v_sub.slug) 
      LIMIT 1;
    END IF;

    IF v_canon_sub IS NOT NULL THEN
      -- Delete existing units and subunits for this subject
      DELETE FROM public.syllabus_units WHERE subject_id = v_sub.id;

      -- Insert units from canonical_syllabus
      FOR v_unit IN 
        SELECT DISTINCT unit_number, 
               COALESCE(unit_name_en, regexp_replace(unit_name, '^ඒකකය\s*\d+\s*:\s*', '')) AS u_title,
               COALESCE(unit_name_si, unit_name) AS u_si,
               unit_name_ta AS u_ta
        FROM public.canonical_syllabus 
        WHERE subject = v_canon_sub
        ORDER BY unit_number
      LOOP
        INSERT INTO public.syllabus_units (subject_id, unit_number, title, sinhala_title, tamil_title)
        VALUES (v_sub.id, v_unit.unit_number, v_unit.u_title, v_unit.u_si, v_unit.u_ta)
        RETURNING id INTO v_unit_id;

        -- Insert subunits with trilingual titles
        INSERT INTO public.syllabus_subunits (unit_id, sub_number, title, sinhala_title, tamil_title, target_hours)
        SELECT 
          v_unit_id, 
          sub_lesson_code, 
          COALESCE(sub_lesson_title_en, sub_lesson_title),
          COALESCE(sub_lesson_title_si, sub_lesson_title),
          sub_lesson_title_ta,
          4
        FROM public.canonical_syllabus
        WHERE subject = v_canon_sub AND unit_number = v_unit.unit_number
        ORDER BY sub_lesson_code;
      END LOOP;
    END IF;
  END LOOP;
END;
$$;

-- 4. Seed any existing users automatically
DO $$
DECLARE
  u RECORD;
BEGIN
  FOR u IN SELECT id FROM public.profiles LOOP
    PERFORM public.seed_user_syllabus_from_canonical(u.id);
  END LOOP;
END;
$$;
